contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint256 v) public payable {
        require(address(this) == c.owner(), "caller must be owner");

        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;
        uint256 depositsBefore = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint256 cBalanceBefore = address(c).balance;

        bool reverted;
        c.withdraw(v); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 cBalanceAfter = address(c).balance;
        uint256 depositsAfter = c.depositsCount(); if (__ESBMC_reverted()) return;
        address ownerAfter = c.owner(); if (__ESBMC_reverted()) return;

        assert(
            (reverted == (v > cBalanceBefore)) &&
            (reverted || (cBalanceAfter == cBalanceBefore - v)) &&
            (depositsAfter == depositsBefore) &&
            (ownerAfter == ownerBefore)
        );
    }
}

